import{_ as s,o as n,a as p,b as l}from"./app.DII24pJb.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"原子操作","link":"/api/SIMD-API/basic_api/atomic_operations/atomic_operations"},{"text":"SetAtomicAdd","link":"/api/SIMD-API/basic_api/atomic_operations/SetAtomicAdd"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/atomic_operations/SetAtomicAdd.md","filePath":"api/SIMD-API/basic_api/atomic_operations/SetAtomicAdd.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1789956443000}'),t={name:"api/SIMD-API/basic_api/atomic_operations/SetAtomicAdd.md"};function i(c,a,e,o,d,h){return n(),p("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>SetAtomicAdd<span id="ZH-CN_TOPIC_0000001487536650"></span></h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_set_atomic_intf.h&quot;</code>。</p><p>对后续目的地址为GM的数据搬运开启原子累加。原子累加过程：将待拷贝的内容和GM已有内容进行求和，然后将求和结果写入GM。SetAtomicAdd接口可通过模板参数设定不同的累加数据类型。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetAtomicAdd</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>设定不同的原子累加操作数据类型。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品，支持的数据类型为int8_t、int16_t、half、bfloat16_t、int32_t、float。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品，支持的数据类型为int8_t、int16_t、half、bfloat16_t、int32_t、float。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品，支持的数据类型为int8_t、int16_t、half、bfloat16_t、int32_t、float。</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品，支持的数据类型为int16_t、half、int32_t、float。</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core，支持的数据类型为int16_t、half、float。</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品，支持的数据类型为float。</li></ul></div><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品，支持的数据通路为UB/L0C Buffer-&gt;GM。</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品，支持的数据通路为UB/L0C Buffer/L1 Buffer-&gt;GM。</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品，支持的数据通路为UB/L0C Buffer/L1 Buffer-&gt;GM。</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品，支持的数据通路为UB/L0C Buffer/L1 Buffer-&gt;GM。</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core，支持的数据通路为UB-&gt;GM。</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品，支持的数据通路为UB-&gt;GM。</li></ul></div><ul><li>累加操作完成后，建议通过<a href="DisableDmaAtomic.html">DisableDmaAtomic</a>关闭原子累加，以免影响后续相关指令功能。</li><li>该接口执行前不会自动清零GM数据。开发者需根据算子逻辑判断是否清零，如需清零，请在执行前手动完成。</li><li>SetAtomicAdd内部已集成与<a href="SetAtomicType.html">SetAtomicType</a>相同的功能。建议调用上述接口时，通过设置模板参数显式指定原子操作的数据类型，无需额外调用SetAtomicType接口。</li></ul><div data-filter="A3,910b"><p><a id="npu_smi_saturation_mode"></a></p><ul><li><p>针对<a href="../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，整数类型和bfloat16_t数据类型的默认计算模式<strong>均为非饱和模式</strong>。原子累加的饱和模式无法通过<a href="../special_register_access/SetSaturationStrategy.html">SetSaturationStrategy</a>或<a href="../special_register_access/SetCtrlSpr_ISASI.html">SetCtrlSpr</a>设置，需通过<code>npu-smi</code>命令在设备级进行配置，各命令的详细说明请参考<a href="https://support.huawei.com/enterprise/zh/atlas-computing/ascend-hdk-pid-252764743?category=reference-guides&amp;subcategory=command-reference">Ascend HDK对应产品的《npu-smi命令参考》</a>。CANN与Ascend HDK的对应关系，请参考<a href="https://www.hiascend.com/developer/download/compatibility">版本配套查询助手</a>。</p><ul><li><p>整数类型：设置饱和模式（溢出值饱和为目标数据类型的最大值或最小值）或截断模式（即非饱和模式，溢出值保留低位、舍弃高位，默认为非饱和模式）。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># 设置整数类型的饱和模式，value取1表示饱和模式，取0表示截断模式（非饱和模式，默认值）</span>
npu-smi<span class="w"> </span><span class="nb">set</span><span class="w"> </span>-t<span class="w"> </span>int-saturation-mode<span class="w"> </span>-d<span class="w"> </span>value

<span class="c1"># 查询当前配置</span>
npu-smi<span class="w"> </span>info<span class="w"> </span>-t<span class="w"> </span>int-saturation-mode
</code></pre></div></li><li><p>bfloat16_t：设置饱和模式（INF饱和为±MAX、NAN饱和为0）或非饱和模式（INF/NAN保持原输出，默认为非饱和模式）。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># 设置bfloat16_t的饱和模式，value取1表示饱和模式，取0表示非饱和模式（默认值）</span>
npu-smi<span class="w"> </span><span class="nb">set</span><span class="w"> </span>-t<span class="w"> </span>bf16-saturation-mode<span class="w"> </span>-d<span class="w"> </span>value

<span class="c1"># 查询当前配置</span>
npu-smi<span class="w"> </span>info<span class="w"> </span>-t<span class="w"> </span>bf16-saturation-mode
</code></pre></div><p>若未设置过bfloat16_t的饱和计算模式（例如设备重启后配置被清除），查询命令的回显如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>The valid state is not set, please set saturation mode first.
Failed to query &quot;bf16-saturation-mode&quot; info.
</code></pre></div></li><li><p>若当前设备不支持上述命令，设置命令与查询命令的回显如下（以int-saturation-mode为例）：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>This device does not support setting int-saturation-mode.
This device does not support querying int-saturation-mode.
</code></pre></div></li><li><p>上述命令需由root用户在物理机+特权容器场景或直通虚拟机+特权容器场景下执行；设备重启后配置不保留，整数类型的饱和模式恢复为默认的截断模式，bfloat16_t的饱和模式配置被清除。</p></li></ul></li></ul></div><h2 id="调用示例">调用示例<span id="section177231425115410"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">UB</span><span class="o">&gt;</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">SIZE</span><span class="o">&gt;</span><span class="p">();</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">DisableDmaAtomic</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">SIZE</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SyncAll</span><span class="p">();</span>

<span class="c1">// 开启原子累加，将Unified Buffer（UB）数据原子累加到GM</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetAtomicAdd</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">dstGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="n">SIZE</span><span class="p">);</span>

<span class="c1">// 关闭原子累加</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DisableDmaAtomic</span><span class="p">();</span>
</code></pre></div><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_basic_api/06_atomic/data_movement_with_atomic_operations/data_movement_with_atomic_operations.asc">DataMovementWithAtomicOperations样例</a>。</p></article></div>`,1)])])}const A=s(t,[["render",i]]);export{v as __pageData,A as default};
